def _tlv(data, pos):
    start, fields = pos, {}
    while pos + 2 <= len(data):
        key, size = data[pos:pos + 2]
        pos += 2
        value = data[pos:pos + size]
        if len(value) != size or key in fields:
            break
        if key == 254:
            if size != 2 or int.from_bytes(value, "little") != sum(data[start:pos]) & 65535:
                break
            return fields, pos + size
        fields[key] = value
        pos += size
    raise PackageError("LuaDB 文件头或校验损坏")


