def native_payload(luadb):
    return NATIVE_PREFIX + struct.pack(">I", len(luadb)) + luadb


def build_package(luadb):
    manifest = inspect_luadb(luadb)
    payload = native_payload(luadb)
    manifest.update(size=len(payload), sha256=hashlib.sha256(payload).hexdigest(), md5=hashlib.md5(payload).hexdigest())
    encoded = json.dumps(manifest, sort_keys=True, separators=(",", ":")).encode("ascii")
    return MAGIC + struct.pack(">I", len(encoded)) + encoded + payload


