def parse_package(data):
    if len(data) > MAX_PACKAGE_BYTES or not data.startswith(MAGIC) or len(data) < len(MAGIC) + 4:
        raise PackageError("请选择本项目打包工具生成的 .air724ota 文件")
    offset = len(MAGIC) + 4
    size = int.from_bytes(data[len(MAGIC):offset], "big")
    if not 1 <= size <= 8192 or offset + size > len(data):
        raise PackageError("升级包清单长度不正确")
    try:
        manifest = json.loads(data[offset:offset + size])
    except (ValueError, UnicodeError, RecursionError):
        raise PackageError("升级包清单损坏") from None
    payload = data[offset + size:]
    prefix_length = len(NATIVE_PREFIX)
    if not payload.startswith(NATIVE_PREFIX) or len(payload) < prefix_length + 4:
        raise PackageError("升级包含 CORE 修改或不支持的原生封装")
    luadb = payload[prefix_length + 4:]
    if len(luadb) != int.from_bytes(payload[prefix_length:prefix_length + 4], "big"):
        raise PackageError("原生升级包长度不正确")
    expected = inspect_luadb(luadb)
    expected.update(size=len(payload), sha256=hashlib.sha256(payload).hexdigest(), md5=hashlib.md5(payload).hexdigest())
    if manifest != expected:
        raise PackageError("升级包清单与实际脚本、版本或校验值不一致")
    return FirmwarePackage(expected, payload)


def parse_upload_package(data):
    """Normalize a web upload without trusting its filename or ZIP metadata."""
    if not 1 <= len(data) <= MAX_PACKAGE_BYTES:
        raise PackageError("升级包为空或超过 464 KiB")
    if data.startswith(MAGIC):
        return parse_package(data)
    if not data.startswith(b"PK\x03\x04"):
        raise PackageError("请选择 Luatools 生成的 .dfota.bin 或本项目的 .air724ota 文件")
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            entries = archive.infolist()
            # Web uploads only accept the script/resource archive, never a
            # factory PAC, CORE patch, nested path or extra archive member.
            if len(entries) != 1 or entries[0].orig_filename != "app.bin":
                raise PackageError("只支持仅含 app.bin 的 Luatools .dfota.bin 脚本资源包")
            app = entries[0]
            if app.flag_bits & (1 | 64) or app.compress_type not in (zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED):
                raise PackageError("升级包使用了不支持的压缩或密码加密方式")
            if not 1 <= app.file_size <= CAPACITY:
                raise PackageError("脚本和资源超出当前 CORE 的 458752 字节容量")
            # ZipFile verifies the local header, member name and overlap bounds.
            # Its reader can truncate at an untrusted file_size, so inflate the
            # compressed bytes ourselves with a hard output limit and EOF check.
            with archive.open(app):
                name_size, extra_size = struct.unpack_from("<HH", data, app.header_offset + 26)
                offset = app.header_offset + 30 + name_size + extra_size
                compressed = data[offset:offset + app.compress_size]
            if len(compressed) != app.compress_size:
                raise PackageError("Luatools 升级包压缩数据不完整")
            if app.compress_type == zipfile.ZIP_DEFLATED:
                decoder = zlib.decompressobj(-zlib.MAX_WBITS)
                luadb = decoder.decompress(compressed, CAPACITY + 1)
                if not decoder.eof or decoder.unconsumed_tail or decoder.unused_data:
                    raise PackageError("Luatools 升级包压缩数据不完整、含多余数据或超出容量")
            else:
                luadb = compressed
            if len(luadb) != app.file_size or len(luadb) > CAPACITY:
                raise PackageError("Luatools 升级包解压长度不正确")
            if zlib.crc32(luadb) != app.CRC:
                raise PackageError("Luatools 升级包完整性校验失败")
        # Reuse the same LuaDB, bytecode and native-payload validation as the
        # optional offline builder. The ZIP itself is never sent to FOTA.
        return parse_package(build_package(luadb))
    except PackageError:
        raise
    except (zipfile.BadZipFile, RuntimeError, OSError, EOFError, ValueError, NotImplementedError, struct.error, zlib.error):
        raise PackageError("无法读取 Luatools 升级包，文件可能损坏") from None


def read_luatools_app(source):
    """Accept a script-only Luatools source archive, or its merged app.bin."""
    if source.startswith(b"PK"):
        try:
            with zipfile.ZipFile(io.BytesIO(source)) as archive:
                entries = archive.infolist()
                apps = [item for item in entries if item.filename == "app.bin"]
                if len(entries) > 8 or len(apps) != 1 or apps[0].file_size > CAPACITY or apps[0].flag_bits & 1:
                    raise PackageError("Luatools 源包必须包含唯一且未加密的 app.bin")
                return archive.read(apps[0])
        except (zipfile.BadZipFile, RuntimeError, OSError):
            raise PackageError("无法读取 Luatools 源包") from None
    return source
